def contains(sorted_values, target):
    low = 0
    high = len(sorted_values) - 1

    while low <= high:
        mid = (low + high) // 2
        if sorted_values[mid] == target:
            return True
        if sorted_values[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return False

print(contains([3, 8, 12, 18, 25, 31, 44], 25))

def total_sales(amounts):
    total = 0
    for amount in amounts:
        total += amount
    return total

print(total_sales([120, 75, 210, 90]))

def merge_sort(values):
    if len(values) <= 1:
        return values

    middle = len(values) // 2
    left = merge_sort(values[:middle])
    right = merge_sort(values[middle:])

    return merge(left, right)


def merge(left, right):
    result = []
    i = j = 0

    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1

    return result + left[i:] + right[j:]

print(merge_sort([9, 4, 7, 1, 3]))

def bubble_sort(values):
    values = values[:]

    for pass_index in range(len(values)):
        for index in range(0, len(values) - pass_index - 1):
            if values[index] > values[index + 1]:
                values[index], values[index + 1] = values[index + 1], values[index]

    return values

print(bubble_sort([5, 1, 4, 2, 8]))

def fibonacci(n):
    if n <= 1:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

print(fibonacci(6))
